package com.aicharacter.v3; public final class WorldSnapshot{public final long timestamp;public final float haruX,catX;public final String haruArea,catArea,weather;public final double light;public final int areaCount,objectCount;private WorldSnapshot(WorldState s){timestamp=System.currentTimeMillis();haruX=s.haruX;catX=s.catX;WorldArea h=s.world.areaAt(haruX),c=s.world.areaAt(catX);haruArea=h==null?"INVALID":h.id;catArea=c==null?"INVALID":c.id;weather=s.environment.weather;light=s.environment.ambientBrightness;areaCount=s.world.areas.size();objectCount=s.world.objects.size();}public static WorldSnapshot observe(WorldState s){return new WorldSnapshot(s);}public String summary(){return "areas="+areaCount+", objects="+objectCount+", girl="+haruArea+"@"+(int)haruX+", cat="+catArea+"@"+(int)catX+", weather="+weather+", light="+String.format(java.util.Locale.US,"%.2f",light);}}
